import assert from "node:assert/strict";
import { test } from "node:test";
import { check, finalLabels, verdict } from "./check.mjs";

const comment = (marker, text = "") => ({
  op: "comment",
  body: `> *This was generated by AI during triage.*\n\n${text}\n\n<!-- qui-triage:${marker} -->`,
});

const promote = [
  { op: "create-issue", state: "ready-for-agent", title: "t", body: "b\n\nFrom discussion #1", labels: [] },
  comment("ready-for-agent", "Tracked in https://github.com/autobrr/qui/issues/9."),
  { op: "add-label", labels: ["ready-for-agent"] },
  { op: "remove-label", labels: ["needs-triage", "needs-confirmation"] },
  { op: "close", reason: "RESOLVED" },
];

const promoteCase = {
  labels: ["bug", "needs-triage", "needs-confirmation"],
  expect: {
    labels: { has: ["bug", "ready-for-agent"], lacks: ["needs-triage", "needs-confirmation"] },
    close: "RESOLVED",
    issue: { state: "ready-for-agent" },
    comment: { marker: "ready-for-agent" },
  },
};

test("finalLabels applies adds and removes in order", () => {
  const writes = [
    { op: "add-label", labels: ["a", "b"] },
    { op: "remove-label", labels: ["a", "x"] },
    { op: "add-label", labels: ["a"] },
  ];
  assert.deepEqual([...finalLabels(["x", "y"], writes)].sort(), ["a", "b", "y"]);
});

test("a promoted bug passes its expectation", () => {
  assert.deepEqual(check(promoteCase, promote), { pass: true, failures: [] });
});

test("a missing write fails each part of the expectation", () => {
  const { pass, failures } = check(promoteCase, []);
  assert.equal(pass, false);
  assert.deepEqual(failures, [
    "label ready-for-agent missing at the end",
    "label needs-triage present at the end",
    "label needs-confirmation present at the end",
    "expected close RESOLVED, got no close",
    "expected one issue, got 0",
    "expected a comment, got none",
  ]);
});

test("the wrong issue state and close reason fail", () => {
  const writes = promote.map((w) =>
    w.op === "create-issue" ? { ...w, state: "ready-for-human" } : w.op === "close" ? { ...w, reason: "DUPLICATE" } : w,
  );
  assert.deepEqual(check(promoteCase, writes).failures, [
    "expected close RESOLVED, got close DUPLICATE",
    "expected an issue in ready-for-agent, got ready-for-human",
  ]);
});

test("issue state accepts a list and checks extra labels", () => {
  const c = { labels: [], expect: { issue: { state: ["ready-for-agent", "ready-for-human"], labels: ["anime"] } } };
  assert.deepEqual(check(c, promote).failures, ["issue lacks label anime"]);
  const withAnime = promote.map((w) => (w.op === "create-issue" ? { ...w, state: "ready-for-human", labels: ["anime"] } : w));
  assert.equal(check(c, withAnime).pass, true);
});

test("noWrite fails on any write and passes on none", () => {
  const c = { labels: ["needs-info"], expect: { noWrite: true } };
  assert.equal(check(c, []).pass, true);
  assert.deepEqual(check(c, [{ op: "add-label", labels: ["bug"] }]).failures, ["expected no write, got add-label"]);
});

test("false forbids a close, an issue, and a comment", () => {
  const c = { labels: [], expect: { close: false, issue: false, comment: false } };
  assert.deepEqual(check(c, promote).failures, [
    "expected no close, got close RESOLVED",
    "expected no issue, got an issue in ready-for-agent",
    "expected no comment, got one",
  ]);
});

test("comment marker and text checks", () => {
  const c = { labels: [], expect: { comment: { marker: ["needs-info"], matches: ["log"], notMatches: ["reload the browser"] } } };
  assert.equal(check(c, [comment("needs-info", "Please upload the log.")]).pass, true);
  assert.deepEqual(check(c, [comment("ready-for-human", "Reload the browser page.")]).failures, [
    "expected comment marker needs-info, got ready-for-human",
    "comment does not match /log/",
    "comment matches /reload the browser/",
  ]);
  assert.deepEqual(check({ labels: [], expect: { comment: { marker: "needs-info" } } }, [{ op: "comment", body: "no marker" }]).failures, [
    "expected comment marker needs-info, got none",
  ]);
});

test("a second comment always fails", () => {
  assert.deepEqual(check({ labels: [], expect: {} }, [comment("needs-info"), comment("needs-info")]).failures, [
    "posted 2 comments, at most one is allowed",
  ]);
});

test("anyOf passes when one alternative passes and reports the closest one", () => {
  const c = {
    labels: ["needs-info"],
    expect: {
      anyOf: [
        { labels: { has: ["ready-for-agent"] }, issue: { state: "ready-for-agent" } },
        { labels: { has: ["ready-for-human"] }, issue: { state: "ready-for-human" } },
      ],
    },
  };
  const human = [
    { op: "create-issue", state: "ready-for-human", title: "t", body: "b", labels: [] },
    { op: "add-label", labels: ["ready-for-human"] },
  ];
  assert.equal(check(c, human).pass, true);
  assert.deepEqual(check(c, [{ op: "add-label", labels: ["ready-for-human"] }]), {
    pass: false,
    failures: ["closest alternative: expected one issue, got 0"],
  });
});

test("verdict needs a third run on a split and fails at half", () => {
  assert.equal(verdict([true, true]), "pass");
  assert.equal(verdict([false, false]), "fail");
  assert.equal(verdict([true, false]), "rerun");
  assert.equal(verdict([true, false, true]), "pass");
  assert.equal(verdict([true, false, false]), "fail");
  assert.equal(verdict([false]), "fail");
});
